// CreateTable creates the Entry_Application table for the specified company (SQLite)
// The db parameter can be either *sql.DB or *sql.Tx
func (t *EntryApplication) CreateTable(db database.Executor, company string) error {
	return t.CreateTableWithDBType(db, company, database.DBTypeSQLite)
}

// CreateTableWithDBType creates the Entry_Application table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *EntryApplication) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, EntryApplicationTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetEntryApplicationPostgresTableSchema()
	} else {
		schema = GetEntryApplicationTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Entry_Application table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *EntryApplication) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, EntryApplicationTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_no)`,
		fmt.Sprintf("%s$Entry_Application$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (application_no)`,
		fmt.Sprintf("%s$Entry_Application$application", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index application: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (account_type, ledger_entry_no, application_no)`,
		fmt.Sprintf("%s$Entry_Application$ledger_entry", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index ledger_entry: %w", err)
	}
	var keys []sift.Key
	for _, spec := range entryApplicationSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, EntryApplicationTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, EntryApplicationTableName, keys)
}

// entryApplicationSIFTSpecs are the table's keys with sum_index_fields
func entryApplicationSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *EntryApplication) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, EntryApplicationTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range entryApplicationSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, EntryApplicationTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: EntryApplicationTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, EntryApplicationTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

